{
  "tools": [
    {
      "name": "add_component",
      "title": "Add Component",
      "toolset": "scene",
      "description": "Add a component to a game object, optionally setting its properties in the same call. The user can undo this. Returns the component's id.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "id": {
            "type": "string",
            "description": "The game object's id, from scene_tree or find_game_objects."
          },
          "type": {
            "type": "string",
            "description": "The component type name, e.g. 'ModelRenderer'. get_component_type documents what exists."
          },
          "properties": {
            "type": "object",
            "description": "Optional json object of property values, e.g. {\"LightColor\": \"1,0.8,0.6,1\", \"Radius\": 512}."
          }
        },
        "required": [
          "id",
          "type"
        ]
      },
      "outputSchema": {
        "type": "object",
        "properties": {
          "Id": {
            "type": "string"
          },
          "Type": {
            "type": "string"
          },
          "GameObject": {
            "type": "string"
          }
        },
        "required": []
      }
    },
    {
      "name": "camera_screenshot",
      "title": "Camera Screenshot",
      "toolset": "scene",
      "description": "Render a camera in the scene and return it as an image. Give any CameraComponent's id or its game object's id, or nothing for the scene's main camera. Works in edit and play mode - editor_camera_screenshot shows the editor viewport instead.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "camera": {
            "type": "string",
            "description": "A CameraComponent id or its game object's id. Empty uses the scene's main camera."
          },
          "width": {
            "type": "integer",
            "description": "Image width in pixels.",
            "minimum": 16,
            "maximum": 4096,
            "default": 1280
          },
          "height": {
            "type": "integer",
            "description": "Image height in pixels.",
            "minimum": 16,
            "maximum": 4096,
            "default": 720
          },
          "includeUi": {
            "type": "boolean",
            "description": "Include any UI the camera renders.",
            "default": true
          }
        },
        "required": []
      },
      "annotations": {
        "readOnlyHint": true
      }
    },
    {
      "name": "create_game_object",
      "title": "Create Game Object",
      "toolset": "scene",
      "description": "Create a game object in the active scene - empty or from a prefab, optionally with components. For putting a model in the scene, spawn_model is quicker. The user can undo this. Returns the new object's id for the other scene tools.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "name": {
            "type": "string",
            "description": "Name for the new object. Empty picks a sensible default."
          },
          "parent": {
            "type": "string",
            "description": "Parent game object id. Empty parents to the scene root."
          },
          "prefab": {
            "type": "string",
            "description": "Prefab asset path to instantiate, from asset_search."
          },
          "position": {
            "type": "string",
            "description": "World position as 'x,y,z'. Default origin."
          },
          "angles": {
            "type": "string",
            "description": "Rotation as 'pitch,yaw,roll'."
          },
          "scale": {
            "type": "string",
            "description": "Scale as 'x,y,z', or a single number for uniform."
          },
          "components": {
            "type": "string",
            "description": "Comma separated component type names to add, e.g. 'ModelRenderer,BoxCollider'."
          }
        },
        "required": []
      },
      "outputSchema": {
        "type": "object",
        "properties": {
          "Id": {
            "type": "string"
          },
          "Name": {
            "type": "string"
          },
          "Position": {
            "type": "string"
          },
          "Components": {
            "type": "array",
            "items": {
              "type": "object",
              "properties": {
                "Id": {
                  "type": "string"
                },
                "Type": {
                  "type": "string"
                },
                "GameObject": {
                  "type": "string"
                }
              },
              "required": []
            }
          }
        },
        "required": []
      }
    },
    {
      "name": "find_game_objects",
      "title": "Find Game Objects",
      "toolset": "scene",
      "description": "Search a scene's game objects by name substring, component type and/or tag. All filters are optional and combine - empty filters list everything. Returns each match with its hierarchy path and id.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "name": {
            "type": "string",
            "description": "Case insensitive substring of the object's name."
          },
          "component": {
            "type": "string",
            "description": "Case insensitive substring of a component type name the object must have."
          },
          "tag": {
            "type": "string",
            "description": "A tag the object must have."
          },
          "scene": {
            "type": "string",
            "description": "Scene name or resource path from list_scenes. Empty for the active scene."
          },
          "limit": {
            "type": "integer",
            "description": "How many matches to return.",
            "minimum": 1,
            "maximum": 500,
            "default": 100
          }
        },
        "required": []
      },
      "annotations": {
        "readOnlyHint": true
      },
      "outputSchema": {
        "type": "object",
        "properties": {
          "Total": {
            "type": "integer",
            "description": "How many matched in total, beyond what's shown."
          },
          "Results": {
            "type": "array",
            "items": {
              "type": "object",
              "properties": {
                "Name": {
                  "type": "string"
                },
                "Id": {
                  "type": "string"
                },
                "Path": {
                  "type": "string",
                  "description": "The object's place in the hierarchy, like 'Map/Props/Barrel'."
                },
                "Enabled": {
                  "type": "boolean"
                },
                "Components": {
                  "type": "array",
                  "items": {
                    "type": "string"
                  }
                }
              },
              "required": []
            }
          },
          "Truncated": {
            "type": "boolean",
            "description": "True when the scene was too big to finish searching."
          }
        },
        "required": []
      }
    },
    {
      "name": "get_component_type",
      "title": "Get Component Type",
      "toolset": "component",
      "description": "Documentation for a component type by name - its class name, display title, description, group, and every inspector property with title, description, type and read-only state. Matches exact names first, then substrings; multiple substring matches come back as a candidate list.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "name": {
            "type": "string",
            "description": "The component's type name, e.g. 'ModelRenderer'. Case insensitive, substrings work."
          }
        },
        "required": [
          "name"
        ]
      },
      "annotations": {
        "readOnlyHint": true
      }
    },
    {
      "name": "get_game_object",
      "title": "Get Game Object",
      "toolset": "scene",
      "description": "Everything about one game object - enabled state, tags, world transform, parent, children, and its components. Set includeComponentProperties to also get every component's serialized properties.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "id": {
            "type": "string",
            "description": "The game object's id, from scene_tree or find_game_objects."
          },
          "includeComponentProperties": {
            "type": "boolean",
            "description": "Include the full serialized properties of every component, not just their types.",
            "default": false
          }
        },
        "required": [
          "id"
        ]
      },
      "annotations": {
        "readOnlyHint": true
      },
      "outputSchema": {
        "type": "object",
        "properties": {
          "Scene": {
            "type": "string"
          },
          "Name": {
            "type": "string"
          },
          "Id": {
            "type": "string"
          },
          "Enabled": {
            "type": "boolean"
          },
          "ActiveInHierarchy": {
            "type": "boolean"
          },
          "Tags": {
            "type": "array",
            "items": {
              "type": "string"
            }
          },
          "Parent": {
            "type": "object",
            "properties": {
              "Id": {
                "type": "string"
              },
              "Name": {
                "type": "string"
              }
            },
            "required": [],
            "description": "The parent. Null when parented to the scene root."
          },
          "WorldPosition": {
            "type": "string"
          },
          "WorldRotation": {
            "type": "string"
          },
          "WorldScale": {
            "type": "string"
          },
          "Components": {
            "type": "array",
            "items": {
              "type": "object",
              "properties": {
                "Type": {
                  "type": "string"
                },
                "Id": {
                  "type": "string"
                },
                "Enabled": {
                  "type": "boolean"
                },
                "Properties": {
                  "description": "The serialized properties. Null unless includeComponentProperties was set."
                }
              },
              "required": []
            }
          },
          "Children": {
            "type": "array",
            "items": {
              "type": "object",
              "properties": {
                "Id": {
                  "type": "string"
                },
                "Name": {
                  "type": "string"
                },
                "Enabled": {
                  "type": "boolean"
                }
              },
              "required": []
            }
          }
        },
        "required": []
      }
    },
    {
      "name": "get_selection",
      "title": "Get Selection",
      "toolset": "scene",
      "description": "What's selected in the editor - the game objects and components the user (or you) has picked.",
      "inputSchema": {
        "type": "object",
        "properties": {},
        "required": []
      },
      "annotations": {
        "readOnlyHint": true
      },
      "outputSchema": {
        "type": "object",
        "properties": {
          "GameObjects": {
            "type": "array",
            "items": {
              "type": "object",
              "properties": {
                "Id": {
                  "type": "string"
                },
                "Name": {
                  "type": "string"
                }
              },
              "required": []
            }
          },
          "Components": {
            "type": "array",
            "items": {
              "type": "object",
              "properties": {
                "Id": {
                  "type": "string"
                },
                "Type": {
                  "type": "string"
                },
                "GameObject": {
                  "type": "string"
                }
              },
              "required": []
            }
          }
        },
        "required": []
      }
    },
    {
      "name": "hammer_asset_usage",
      "title": "Asset Usage",
      "toolset": "hammer",
      "description": "Which assets the map uses and how heavily - mesh materials with how many faces, triangles and square units of surface they cover, models and other assets in entity keyvalues, and resources on game object components. Counts the map as placed: everything inside a prefab counts once per placement, nested prefabs included, so Nodes, Faces and Triangles track what gets drawn. With no asset, lists every asset sorted by 'sortBy'; give an asset to list where it's placed - inside a prefab, that's the prefab node placed in the map.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "asset": {
            "type": "string",
            "description": "An asset path to find users of. Empty summarises everything."
          },
          "sortBy": {
            "type": "string",
            "description": "Sort the summary by Nodes, Faces, Triangles or Area.",
            "default": "Nodes"
          },
          "includePrefabs": {
            "type": "boolean",
            "description": "Count what's inside prefabs placed in the map, not just the map's own nodes.",
            "default": true
          },
          "limit": {
            "type": "integer",
            "description": "How many entries to return.",
            "minimum": 1,
            "maximum": 1000,
            "default": 200
          }
        },
        "required": []
      },
      "annotations": {
        "readOnlyHint": true
      }
    },
    {
      "name": "hammer_create_game_object",
      "title": "Create Game Object",
      "toolset": "hammer",
      "description": "Put a game object in the open map - empty, from a prefab, and/or with components and their properties set in the same call. This is how s&box gameplay goes in a map. The user can undo the creation. Returns the new node, whose GameObject field is the object's guid.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "name": {
            "type": "string",
            "description": "Name for the object. Empty uses the prefab's name, or 'GameObject'."
          },
          "position": {
            "type": "string",
            "description": "World position as 'x,y,z'."
          },
          "angles": {
            "type": "string",
            "description": "Rotation as 'pitch,yaw,roll'."
          },
          "prefab": {
            "type": "string",
            "description": "Prefab asset path to instantiate, from asset_search type:prefab."
          },
          "components": {
            "type": "object",
            "description": "Components to add, as a json object of type name to properties - e.g. {\"ModelRenderer\": {\"Model\": \"models/dev/box.vmdl\"}, \"BoxCollider\": {}}. get_component_type documents types and properties. A type the prefab already has gets its properties set instead."
          }
        },
        "required": []
      },
      "outputSchema": {
        "type": "object",
        "properties": {
          "Id": {
            "type": "integer"
          },
          "Kind": {
            "type": "string"
          },
          "Name": {
            "type": "string"
          },
          "ClassName": {
            "type": "string"
          },
          "Description": {
            "type": "string"
          },
          "Position": {
            "type": "string"
          },
          "Parent": {
            "type": "integer"
          },
          "GameObject": {
            "type": "string"
          },
          "Selected": {
            "type": "boolean"
          },
          "Visible": {
            "type": "boolean"
          }
        },
        "required": []
      }
    },
    {
      "name": "hammer_get_node",
      "title": "Get Node",
      "toolset": "hammer",
      "description": "Everything about one map node - transform, parent and children, and depending on its kind: an entity's class and every keyvalue, a mesh's face materials, a game object's id and components, or an instance's target.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "id": {
            "type": "integer",
            "description": "The node id, from hammer_find_nodes or hammer_get_selection."
          },
          "includeComponentProperties": {
            "type": "boolean",
            "description": "Include the full serialized properties of a game object's components, not just their types.",
            "default": false
          }
        },
        "required": [
          "id"
        ]
      },
      "annotations": {
        "readOnlyHint": true
      },
      "outputSchema": {
        "type": "object",
        "properties": {
          "Angles": {
            "type": "string"
          },
          "Scale": {
            "type": "string"
          },
          "ChildCount": {
            "type": "integer"
          },
          "Children": {
            "type": "array",
            "items": {
              "type": "object",
              "properties": {
                "Id": {
                  "type": "integer"
                },
                "Kind": {
                  "type": "string"
                },
                "Name": {
                  "type": "string"
                },
                "ClassName": {
                  "type": "string"
                },
                "Description": {
                  "type": "string"
                },
                "Position": {
                  "type": "string"
                },
                "Parent": {
                  "type": "integer"
                },
                "GameObject": {
                  "type": "string"
                },
                "Selected": {
                  "type": "boolean"
                },
                "Visible": {
                  "type": "boolean"
                }
              },
              "required": []
            }
          },
          "EntityClassTitle": {
            "type": "string"
          },
          "KeyValues": {
            "type": "object",
            "additionalProperties": {
              "type": "string"
            }
          },
          "Materials": {
            "type": "array",
            "items": {
              "type": "string"
            }
          },
          "Components": {
            "type": "array",
            "items": {
              "type": "object",
              "properties": {
                "Type": {
                  "type": "string"
                },
                "Id": {
                  "type": "string"
                },
                "Enabled": {
                  "type": "boolean"
                },
                "Properties": {}
              },
              "required": []
            }
          },
          "Tags": {
            "type": "array",
            "items": {
              "type": "string"
            }
          },
          "InstanceTarget": {
            "type": "integer"
          },
          "Id": {
            "type": "integer"
          },
          "Kind": {
            "type": "string"
          },
          "Name": {
            "type": "string"
          },
          "ClassName": {
            "type": "string"
          },
          "Description": {
            "type": "string"
          },
          "Position": {
            "type": "string"
          },
          "Parent": {
            "type": "integer"
          },
          "GameObject": {
            "type": "string"
          },
          "Selected": {
            "type": "boolean"
          },
          "Visible": {
            "type": "boolean"
          }
        },
        "required": []
      }
    },
    {
      "name": "hammer_get_selection",
      "title": "Get Selection",
      "toolset": "hammer",
      "description": "What's selected in Hammer - the selection mode (Groups, Objects, Meshes, Vertices, Edges, Faces...), the pivot position, and the selected nodes. In a component mode like Faces the nodes list is the objects owning the selection.",
      "inputSchema": {
        "type": "object",
        "properties": {},
        "required": []
      },
      "annotations": {
        "readOnlyHint": true
      },
      "outputSchema": {
        "type": "object",
        "properties": {
          "Mode": {
            "type": "string"
          },
          "Pivot": {
            "type": "string"
          },
          "Count": {
            "type": "integer"
          },
          "Nodes": {
            "type": "array",
            "items": {
              "type": "object",
              "properties": {
                "Id": {
                  "type": "integer"
                },
                "Kind": {
                  "type": "string"
                },
                "Name": {
                  "type": "string"
                },
                "ClassName": {
                  "type": "string"
                },
                "Description": {
                  "type": "string"
                },
                "Position": {
                  "type": "string"
                },
                "Parent": {
                  "type": "integer"
                },
                "GameObject": {
                  "type": "string"
                },
                "Selected": {
                  "type": "boolean"
                },
                "Visible": {
                  "type": "boolean"
                }
              },
              "required": []
            }
          }
        },
        "required": []
      }
    },
    {
      "name": "hammer_overlays_to_decals",
      "title": "Overlays To Decals",
      "toolset": "hammer",
      "description": "Replace overlays with Decal game objects - both static overlays (kind Overlay) and info_overlay entities. Each overlay's material becomes a .decal asset (made once per material from its color, normal and roughness textures, reused if one already exists in the folder), and a game object with a Decal component goes on the surface the overlay covered, the same size and facing the same way. One undo step covers the whole swap. Set dryRun to see what would happen first.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "ids": {
            "type": "array",
            "items": {
              "type": "integer"
            },
            "description": "Overlay node ids to convert. Empty converts every overlay in the map."
          },
          "decalFolder": {
            "type": "string",
            "description": "Folder in the project's assets for the generated .decal files.",
            "default": "decals/overlays"
          },
          "keepOverlays": {
            "type": "boolean",
            "description": "Keep the overlays after creating the decals, instead of deleting them.",
            "default": false
          },
          "dryRun": {
            "type": "boolean",
            "description": "Only report what would be converted - create and delete nothing.",
            "default": false
          }
        },
        "required": []
      }
    },
    {
      "name": "hammer_set_components",
      "title": "Set Components",
      "toolset": "hammer",
      "description": "Edit a map game object's components - add components, set their properties, remove them. Properties take the serialized forms hammer_get_node shows with includeComponentProperties. Everything validates before anything changes. Hammer can't undo component edits yet, so read the current values first if you might need to put them back.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "id": {
            "type": "integer",
            "description": "The game object's node id, from hammer_find_nodes kind:GameObject."
          },
          "components": {
            "type": "object",
            "description": "A json object of component type to properties, e.g. {\"PointLight\": {\"Radius\": 512}}. A type the object doesn't have yet gets added."
          },
          "remove": {
            "type": "array",
            "items": {
              "type": "string"
            },
            "description": "Component type names to remove."
          }
        },
        "required": [
          "id"
        ]
      },
      "outputSchema": {
        "type": "object",
        "properties": {
          "Angles": {
            "type": "string"
          },
          "Scale": {
            "type": "string"
          },
          "ChildCount": {
            "type": "integer"
          },
          "Children": {
            "type": "array",
            "items": {
              "type": "object",
              "properties": {
                "Id": {
                  "type": "integer"
                },
                "Kind": {
                  "type": "string"
                },
                "Name": {
                  "type": "string"
                },
                "ClassName": {
                  "type": "string"
                },
                "Description": {
                  "type": "string"
                },
                "Position": {
                  "type": "string"
                },
                "Parent": {
                  "type": "integer"
                },
                "GameObject": {
                  "type": "string"
                },
                "Selected": {
                  "type": "boolean"
                },
                "Visible": {
                  "type": "boolean"
                }
              },
              "required": []
            }
          },
          "EntityClassTitle": {
            "type": "string"
          },
          "KeyValues": {
            "type": "object",
            "additionalProperties": {
              "type": "string"
            }
          },
          "Materials": {
            "type": "array",
            "items": {
              "type": "string"
            }
          },
          "Components": {
            "type": "array",
            "items": {
              "type": "object",
              "properties": {
                "Type": {
                  "type": "string"
                },
                "Id": {
                  "type": "string"
                },
                "Enabled": {
                  "type": "boolean"
                },
                "Properties": {}
              },
              "required": []
            }
          },
          "Tags": {
            "type": "array",
            "items": {
              "type": "string"
            }
          },
          "InstanceTarget": {
            "type": "integer"
          },
          "Id": {
            "type": "integer"
          },
          "Kind": {
            "type": "string"
          },
          "Name": {
            "type": "string"
          },
          "ClassName": {
            "type": "string"
          },
          "Description": {
            "type": "string"
          },
          "Position": {
            "type": "string"
          },
          "Parent": {
            "type": "integer"
          },
          "GameObject": {
            "type": "string"
          },
          "Selected": {
            "type": "boolean"
          },
          "Visible": {
            "type": "boolean"
          }
        },
        "required": []
      }
    },
    {
      "name": "remove_component",
      "title": "Remove Component",
      "toolset": "scene",
      "description": "Remove a component. Give the component's id, or its game object's id plus a type name. The user can undo this. Removal applies at the end of the frame, so reading the object in the same batch still shows it.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "id": {
            "type": "string",
            "description": "The component's id, or its game object's id."
          },
          "type": {
            "type": "string",
            "description": "The component type to remove, when id is a game object."
          }
        },
        "required": [
          "id"
        ]
      }
    },
    {
      "name": "scene_tree",
      "title": "Scene Tree",
      "toolset": "scene",
      "description": "The game object hierarchy of an open scene - every object's name, id, enabled state and component types, nested like the editor's hierarchy panel. Use the ids with get_game_object to dig into a specific object.",
      "inputSchema": {
        "type": "object",
